-- Existing restaurants retain disabled operational features; default-branch grants preserve membership.
CREATE TABLE operational_settings(restaurant_id uuid PRIMARY KEY REFERENCES restaurants(id),content jsonb NOT NULL DEFAULT '{"kitchen":false,"tables":false,"pos":false,"cash":false,"delivery":false,"inventory":false,"coupons":false}',version integer NOT NULL DEFAULT 0);
CREATE TABLE branch_access(restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,membership_id uuid NOT NULL REFERENCES restaurant_memberships(id),PRIMARY KEY(restaurant_id,branch_id,membership_id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
INSERT INTO branch_access SELECT m.restaurant_id,b.id,m.id FROM restaurant_memberships m JOIN branches b ON b.restaurant_id=m.restaurant_id AND b.is_default;
ALTER TABLE restaurant_memberships ADD CONSTRAINT membership_tenant_identity UNIQUE(restaurant_id,id);
ALTER TABLE branch_access ADD CONSTRAINT access_membership_tenant FOREIGN KEY(restaurant_id,membership_id) REFERENCES restaurant_memberships(restaurant_id,id);
CREATE TABLE staff_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,email text NOT NULL,role text NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed_at timestamptz,revoked_at timestamptz,invited_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE kitchen_stations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true,fallback boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE UNIQUE INDEX station_fallback ON kitchen_stations(restaurant_id,branch_id) WHERE fallback;
CREATE TABLE station_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,membership_id uuid NOT NULL,station_id uuid NOT NULL,FOREIGN KEY(restaurant_id,branch_id,station_id) REFERENCES kitchen_stations(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,membership_id) REFERENCES restaurant_memberships(restaurant_id,id),UNIQUE(membership_id,station_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE station_routes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,item_id uuid NOT NULL,station_id uuid NOT NULL,FOREIGN KEY(restaurant_id,branch_id,station_id) REFERENCES kitchen_stations(restaurant_id,branch_id,id),UNIQUE(restaurant_id,branch_id,item_id,station_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE kitchen_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,order_id uuid NOT NULL,state text NOT NULL DEFAULT 'WAITING' CHECK(state IN('WAITING','PREPARING','READY','CANCELLED')),version integer NOT NULL DEFAULT 0,FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),UNIQUE(order_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE kitchen_work(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,ticket_id uuid NOT NULL,order_item_id uuid NOT NULL REFERENCES order_items(id),station_id uuid NOT NULL,snapshot jsonb NOT NULL,state text NOT NULL DEFAULT 'WAITING' CHECK(state IN('WAITING','PREPARING','READY','CANCELLED')),delay_reason text,version integer NOT NULL DEFAULT 0,FOREIGN KEY(restaurant_id,branch_id,ticket_id) REFERENCES kitchen_tickets(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id,station_id) REFERENCES kitchen_stations(restaurant_id,branch_id,id),UNIQUE(order_item_id,station_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE operational_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,entity text NOT NULL,entity_id uuid NOT NULL,action text NOT NULL,actor_id uuid REFERENCES users(id),reason text NOT NULL,content jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE dining_areas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE dining_tables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,area_id uuid NOT NULL,name text NOT NULL,seats integer NOT NULL CHECK(seats>0 AND seats<=100),active boolean NOT NULL DEFAULT true,blocked_reason text,cleaning boolean NOT NULL DEFAULT false,qr_hash text UNIQUE,qr_generation integer NOT NULL DEFAULT 0,FOREIGN KEY(restaurant_id,branch_id,area_id) REFERENCES dining_areas(restaurant_id,branch_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE service_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,table_id uuid NOT NULL,party integer NOT NULL CHECK(party>0),waiter_id uuid REFERENCES users(id),reservation_id uuid,expected_end timestamptz NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','CLOSED')),closed_at timestamptz,activation_hash text NOT NULL,version integer NOT NULL DEFAULT 0,FOREIGN KEY(restaurant_id,branch_id,table_id) REFERENCES dining_tables(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,reservation_id) REFERENCES reservations(restaurant_id,id),UNIQUE(reservation_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE UNIQUE INDEX one_table_visit ON service_sessions(table_id) WHERE status='OPEN';
CREATE TABLE table_guest_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,service_session_id uuid NOT NULL,commerce_session_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,FOREIGN KEY(restaurant_id,branch_id,service_session_id) REFERENCES service_sessions(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,commerce_session_id) REFERENCES commerce_sessions(restaurant_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE session_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,service_session_id uuid NOT NULL,order_id uuid NOT NULL UNIQUE,FOREIGN KEY(restaurant_id,branch_id,service_session_id) REFERENCES service_sessions(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE cash_registers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE cash_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,register_id uuid NOT NULL,opened_by uuid NOT NULL REFERENCES users(id),opening bigint NOT NULL CHECK(opening>=0),currency varchar(3) NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','CLOSED')),counted bigint,expected bigint,variance bigint,closed_at timestamptz,closed_by uuid REFERENCES users(id),reviewed_at timestamptz,reviewed_by uuid REFERENCES users(id),FOREIGN KEY(restaurant_id,branch_id,register_id) REFERENCES cash_registers(restaurant_id,branch_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE UNIQUE INDEX one_cash_session ON cash_sessions(register_id) WHERE status='OPEN';
CREATE TABLE cash_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,cash_session_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('SALE','REFUND','IN','OUT')),amount bigint NOT NULL CHECK(amount>0),order_id uuid,refund_id uuid,operation_key text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,FOREIGN KEY(restaurant_id,branch_id,cash_session_id) REFERENCES cash_sessions(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),FOREIGN KEY(restaurant_id,refund_id) REFERENCES refund_requests(restaurant_id,id),UNIQUE(restaurant_id,branch_id,operation_key),UNIQUE(order_id),UNIQUE(refund_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE delivery_zones(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,description text NOT NULL,fee bigint NOT NULL CHECK(fee>=0),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE delivery_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,order_id uuid NOT NULL UNIQUE,rider_id uuid NOT NULL REFERENCES users(id),state text NOT NULL DEFAULT 'ASSIGNED' CHECK(state IN('ASSIGNED','ACCEPTED','PICKED_UP','EN_ROUTE','DELIVERED','FAILED')),version integer NOT NULL DEFAULT 0,FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE ingredients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,unit text NOT NULL CHECK(unit IN('g','ml','each')),threshold bigint NOT NULL DEFAULT 0 CHECK(threshold>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE stock_locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE stock_balances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,ingredient_id uuid NOT NULL,location_id uuid NOT NULL,quantity bigint NOT NULL DEFAULT 0 CHECK(quantity>=0),reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity),FOREIGN KEY(restaurant_id,branch_id,ingredient_id) REFERENCES ingredients(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id,location_id) REFERENCES stock_locations(restaurant_id,branch_id,id),UNIQUE(ingredient_id,location_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,ingredient_id uuid NOT NULL,location_id uuid NOT NULL,quantity bigint NOT NULL,kind text NOT NULL CHECK(kind IN('OPENING','RECEIPT','ADJUSTMENT','WASTE','CONSUMPTION','PREPARED_WASTE')),operation_key text NOT NULL,order_id uuid,reason text NOT NULL,actor_id uuid REFERENCES users(id),FOREIGN KEY(restaurant_id,branch_id,ingredient_id) REFERENCES ingredients(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id,location_id) REFERENCES stock_locations(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),UNIQUE(restaurant_id,branch_id,operation_key),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE recipe_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,item_id uuid NOT NULL,variant_id uuid,option_id uuid,location_id uuid NOT NULL,version integer NOT NULL,active boolean NOT NULL DEFAULT true,FOREIGN KEY(restaurant_id,branch_id,location_id) REFERENCES stock_locations(restaurant_id,branch_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE UNIQUE INDEX recipe_active ON recipe_versions(restaurant_id,branch_id,item_id,COALESCE(variant_id,'00000000-0000-0000-0000-000000000000'),COALESCE(option_id,'00000000-0000-0000-0000-000000000000')) WHERE active;
CREATE TABLE recipe_components(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,recipe_id uuid NOT NULL,ingredient_id uuid NOT NULL,quantity bigint NOT NULL CHECK(quantity>0),FOREIGN KEY(restaurant_id,branch_id,recipe_id) REFERENCES recipe_versions(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id,ingredient_id) REFERENCES ingredients(restaurant_id,branch_id,id),UNIQUE(recipe_id,ingredient_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE inventory_tracking(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,item_id uuid NOT NULL,UNIQUE(restaurant_id,branch_id,item_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE stock_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,order_id uuid NOT NULL,order_item_id uuid NOT NULL REFERENCES order_items(id),recipe_id uuid NOT NULL,ingredient_id uuid NOT NULL,location_id uuid NOT NULL,quantity bigint NOT NULL CHECK(quantity>0),state text NOT NULL DEFAULT 'RESERVED' CHECK(state IN('RESERVED','CONSUMED','RELEASED')),FOREIGN KEY(restaurant_id,branch_id,recipe_id) REFERENCES recipe_versions(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id,ingredient_id) REFERENCES ingredients(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id,location_id) REFERENCES stock_locations(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),UNIQUE(order_item_id,recipe_id,ingredient_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE coupons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,code text NOT NULL,content jsonb NOT NULL,version integer NOT NULL DEFAULT 0,UNIQUE(restaurant_id,branch_id,code),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE coupon_uses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,coupon_id uuid NOT NULL,order_id uuid NOT NULL UNIQUE,user_id uuid REFERENCES users(id),state text NOT NULL DEFAULT 'RESERVED' CHECK(state IN('RESERVED','REDEEMED','RELEASED')),snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 minutes',FOREIGN KEY(restaurant_id,branch_id,coupon_id) REFERENCES coupons(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE customer_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),note text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE verified_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,order_id uuid NOT NULL UNIQUE,user_id uuid REFERENCES users(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),comment text NOT NULL,status text NOT NULL DEFAULT 'PUBLISHED' CHECK(status IN('PUBLISHED','HIDDEN')),response text,FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE review_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,review_id uuid NOT NULL,reporter_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,FOREIGN KEY(restaurant_id,branch_id,review_id) REFERENCES verified_reviews(restaurant_id,branch_id,id),UNIQUE(review_id,reporter_id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE review_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,order_id uuid NOT NULL UNIQUE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed_at timestamptz,FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE TABLE export_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,requested_by uuid NOT NULL REFERENCES users(id),kind text NOT NULL,format text NOT NULL CHECK(format IN('csv','pdf')),filters jsonb NOT NULL,state text NOT NULL DEFAULT 'PENDING' CHECK(state IN('PENDING','DONE','FAILED')),bytes bytea,error text,expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,branch_id,id),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id));
CREATE INDEX kitchen_board ON kitchen_work(restaurant_id,branch_id,station_id,state);
CREATE INDEX service_overlap ON service_sessions(restaurant_id,branch_id,expected_end) WHERE status='OPEN';
CREATE INDEX stock_order ON stock_reservations(restaurant_id,order_id);
CREATE INDEX export_pending ON export_jobs(state,created_at);
CREATE FUNCTION deny_ledger_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only ledger'; END $$;
CREATE TRIGGER stock_immutable BEFORE UPDATE OR DELETE ON stock_movements FOR EACH ROW EXECUTE FUNCTION deny_ledger_change();
CREATE TRIGGER cash_immutable BEFORE UPDATE OR DELETE ON cash_movements FOR EACH ROW EXECUTE FUNCTION deny_ledger_change();
CREATE FUNCTION protect_closed_cash() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='CLOSED' AND (to_jsonb(NEW)-'reviewed_at'-'reviewed_by') IS DISTINCT FROM (to_jsonb(OLD)-'reviewed_at'-'reviewed_by') THEN RAISE EXCEPTION 'Closed cash session is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cash_closed_immutable BEFORE UPDATE ON cash_sessions FOR EACH ROW EXECUTE FUNCTION protect_closed_cash();
INSERT INTO permissions(code,module,description) VALUES('staff.manage','operations','staff.manage'),('kitchen.configure','operations','kitchen.configure'),('kitchen.read','operations','kitchen.read'),('kitchen.update','operations','kitchen.update'),('kitchen.correct','operations','kitchen.correct'),('tables.manage','operations','tables.manage'),('pos.create','operations','pos.create'),('cash_sessions.manage','operations','cash_sessions.manage'),('cash_sessions.close','operations','cash_sessions.close'),('payments.collect','operations','payments.collect'),('refunds.request','operations','refunds.request'),('delivery.assign','operations','delivery.assign'),('delivery.update_assigned','operations','delivery.update_assigned'),('inventory.adjust','operations','inventory.adjust'),('coupons.manage','operations','coupons.manage'),('customers.read','operations','customers.read'),('customers.notes','operations','customers.notes'),('customers.export','operations','customers.export'),('reviews.manage','operations','reviews.manage'),('exports.generate','operations','exports.generate'),('operations.configure','operations','operations.configure') ON CONFLICT DO NOTHING;
INSERT INTO roles(name,is_system) VALUES('cashier',true),('chef',true),('waiter',true),('rider',true),('accountant',true) ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.restaurant_id IS NULL AND r.name IN('owner','manager') AND p.module='operations' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.restaurant_id IS NULL AND r.name='chef' AND p.code IN('kitchen.read','kitchen.update') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.restaurant_id IS NULL AND r.name='cashier' AND p.code IN('pos.create','cash_sessions.manage','cash_sessions.close','payments.collect','orders:read') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.restaurant_id IS NULL AND r.name='waiter' AND p.code IN('tables.manage','pos.create','orders:read') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.restaurant_id IS NULL AND r.name='rider' AND p.code IN('delivery.update_assigned') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.restaurant_id IS NULL AND r.name='accountant' AND p.code IN('exports.generate','customers.export','reports:read') ON CONFLICT DO NOTHING;
ALTER TABLE carts ADD COLUMN operational_context jsonb NOT NULL DEFAULT '{}';
-- Default-branch-only onboarding; no broad all-branch grant.
CREATE FUNCTION default_membership_branch() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 INSERT INTO branch_access(restaurant_id,branch_id,membership_id) SELECT NEW.restaurant_id,id,NEW.id FROM branches WHERE restaurant_id=NEW.restaurant_id AND is_default ON CONFLICT DO NOTHING; RETURN NEW;
END $$;
CREATE TRIGGER membership_default_branch AFTER INSERT ON restaurant_memberships FOR EACH ROW EXECUTE FUNCTION default_membership_branch();
